script:
(function () {
  try {
    if (!document.querySelector('link[data-security-poppins]')) {
      var fontLink = document.createElement('link');
      fontLink.rel = 'stylesheet';
      fontLink.setAttribute('data-security-poppins', '1');
      fontLink.href =
        'https://fonts.googleapis.com/css2?family=Poppins:' +
        'wght@400;500;600;700&display=swap';

      document.head.appendChild(fontLink);
    }
  } catch (error) {
    console.warn('Security font loading failed:', error);
  }

  var roles =
    (window.frappe && frappe.user_roles) || [];

  var isAdministrator =
    roles.indexOf('System Manager') >= 0 ||
    roles.indexOf('Administrator') >= 0 ||
    (
      window.frappe &&
      frappe.user &&
      frappe.user.name === 'Administrator'
    );

  var tiles =
    root_element.querySelectorAll('.secn-tile');

  tiles.forEach(function (tile) {
    var requiredRoles =
      (tile.getAttribute('data-roles') || '')
        .split(',')
        .map(function (role) {
          return role.trim();
        })
        .filter(Boolean);

    if (
      requiredRoles.length &&
      !isAdministrator &&
      !requiredRoles.some(function (role) {
        return roles.indexOf(role) >= 0;
      })
    ) {
      tile.classList.add('secn-hide');
      return;
    }

    var referenceType =
      tile.getAttribute('data-ref-type');

    var referenceName =
      tile.getAttribute('data-ref-name');

    if (
      !referenceType ||
      !referenceName ||
      !window.frappe ||
      !frappe.db ||
      !frappe.db.exists
    ) {
      return;
    }

    frappe.db.exists(referenceType, referenceName)
      .then(function (exists) {
        if (!exists) {
          tile.classList.add('secn-hide');
        }
      })
      .catch(function () {
        /*
         * Keep the tile visible when existence checking
         * is unavailable. Frappe permissions will still
         * control access to the destination.
         */
      });
  });
})();

style:
.secn {
  padding: 4px 2px;
  font-family:
    'Poppins',
    var(--font-stack),
    'Inter',
    sans-serif;
}

.secn-title {
  margin: 0 0 10px 2px;
  color: #8a8f98;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: .06em;
  text-transform: uppercase;
}

.secn-title-admin {
  margin-top: 18px;
}

.secn-grid {
  display: grid;
  grid-template-columns:
    repeat(auto-fill, minmax(190px, 1fr));
  gap: 10px;
}

.secn-tile {
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 13px 15px;
  border: 1px solid var(--border-color, #e2e4e9);
  border-radius: 10px;
  background: var(--card-bg, #fff);
  color: inherit;
  text-decoration: none;
  transition:
    box-shadow .18s ease,
    transform .18s ease;
}

.secn-tile:hover {
  box-shadow: 0 2px 6px rgba(0, 0, 0, .06);
  transform: translateY(-1px);
  text-decoration: none;
}

.secn-tile:hover .secn-lb,
.secn-tile:hover .secn-sub {
  text-decoration: none;
}

.secn-ic {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 36px;
  height: 36px;
  border-radius: 9px;
  flex: 0 0 auto;
  color: inherit;
}

.secn-ic svg {
  width: 18px;
  height: 18px;
}

.secn-tx {
  display: flex;
  min-width: 0;
  flex-direction: column;
}

.secn-lb {
  display: block;
  font-size: 13.5px;
  font-weight: 600;
  line-height: 1.2;
}

.secn-sub {
  display: block;
  margin-top: 2px;
  color: #8a8f98;
  font-size: 11px;
  line-height: 1.3;
}

.secn-hide {
  display: none !important;
}

@media (max-width: 767px) {
  .secn-grid {
    grid-template-columns: 1fr;
  }
}
